   943    SelectorList* ComplexSelector::resolve_parent_refs(SelectorStack pstack, Backtraces& traces, bool implicit_parent)
   944    {
   945
   946      std::vector<std::vector<ComplexSelectorObj>> vars;
   947
   948      auto parent = pstack.back();
   949
   950      if (has_real_parent_ref() && !parent) {
   951        throw Exception::TopLevelParent(traces, pstate());
   952      }
   953
   954      if (!chroots() && parent) {
   955
   956        if (!has_real_parent_ref() && !implicit_parent) {
   957          SelectorList* retval = SASS_MEMORY_NEW(SelectorList, pstate(), 1);
   958          retval->append(this);
   959          return retval;
   960        }
   961
   962        vars.push_back(parent->elements());
   963      }
   964
   965      for (auto sel : elements()) {
   966        if (CompoundSelectorObj comp = Cast<CompoundSelector>(sel)) {
   967          auto asd = comp->resolve_parent_refs(pstack, traces, implicit_parent);
   968          if (asd.size() > 0) vars.push_back(asd);
   969        }
   970        else {
   971          // ToDo: merge together sequences whenever possible
   972          auto cont = SASS_MEMORY_NEW(ComplexSelector, pstate());
   973          cont->append(sel);
   974          vars.push_back({ cont });
   975        }
   976      }
   977
   978      // Need complex selectors to preserve linefeeds
   979      std::vector<std::vector<ComplexSelectorObj>> res = permutateAlt(vars);
   980
   981      // std::reverse(std::begin(res), std::end(res));
   982
   983      auto lst = SASS_MEMORY_NEW(SelectorList, pstate());
   984      for (auto items : res) {
   985        if (items.size() > 0) {
   986          ComplexSelectorObj first = SASS_MEMORY_COPY(items[0]);
   987          first->hasPreLineFeed(first->hasPreLineFeed() || (!has_real_parent_ref() && hasPreLineFeed()));
   988          // ToDo: remove once we know how to handle line feeds
   989          // ToDo: currently a mashup between ruby and dart sass
   990          // if (has_real_parent_ref()) first->has_line_feed(false);
   991          // first->has_line_break(first->has_line_break() || has_line_break());
   992          first->chroots(true); // has been resolved by now
   993          for (size_t i = 1; i < items.size(); i += 1) {
   994            first->concat(items[i]);
   995          }
   996          lst->append(first);
   997        }
   998      }
   999
  1000      return lst;
  1001
  1002    }
