  1004    SelectorList* SelectorList::resolve_parent_refs(SelectorStack pstack, Backtraces& traces, bool implicit_parent)
  1005    {
  1006      SelectorList* rv = SASS_MEMORY_NEW(SelectorList, pstate());
  1007      for (auto sel : elements()) {
  1008        // Note: this one is tricky as we get back a pointer from resolve parents ...
  1009        SelectorListObj res = sel->resolve_parent_refs(pstack, traces, implicit_parent);
  1010        // Note: ... and concat will only append the items in elements
  1011        // Therefore by passing it directly, the container will leak!
  1012        rv->concat(res);
  1013      }
  1014      return rv;
  1015    }
